import {WORKSPACE_STORE,LEGACY_SKILL_STORE,emptyWorkspace,createWorkspaceProject,addWorkspaceProject,workspaceProject,workspaceSkill,addWorkspaceSkill,updateWorkspaceSkill,readWorkspace,workspaceProjectBackup,readWorkspaceProjectBackup,restoreWorkspaceProject,recoverLegacyWorkspace} from './workspace.mjs';
import {projectDirectoryMarkup,skillDirectoryMarkup} from './workspace-view.mjs';
import {PATHS,uid,copy,slugify,blankProject,newStep,inputFor,definitionValue,validate,compile,importMarkdownFiles,readProject,safePath,sourceBytes,resourceKind,preserveSource} from './core.mjs';
import {writeZip,readZip} from './zip.mjs';
import {demoProject} from './demo.mjs';
import {CONTRACT_FIELDS,resourceComplete,resourceMarkdown,applyResourceAnalysis,draftResource} from './resources.mjs';

import {independentReviewState,createIndependentReviewPacket,recordIndependentReview,sourceTriage} from './independent-review.mjs';
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
let workspace=emptyWorkspace(),project=null,activeProjectId='',storageAvailable=true,storageBlocked=false,recoveryText='',startupNotice='';
try{
 const stored=localStorage.getItem(WORKSPACE_STORE);
 if(stored){try{workspace=readWorkspace(stored);}catch{storageBlocked=true;recoveryText=stored;startupNotice='Your saved projects could not be reopened. Download a recovery copy before starting a new workspace.';}}
 else {const legacy=localStorage.getItem(LEGACY_SKILL_STORE);if(legacy){try{workspace=recoverLegacyWorkspace(legacy);}catch{storageBlocked=true;recoveryText=legacy;startupNotice='Your earlier draft could not be reopened. Download a recovery copy before starting a new workspace.';}}}
}catch{storageAvailable=false;}
let page='projects',view='guided',selected='',tab='definition',referenceId='',referenceTab='files',packageFile='SKILL.md';
let history=[],future=[],dialogState=null,pendingImport=null,pendingImportProjectId='',importDestination='',importRequestToken=0,restoreRequest={mode:'project',projectId:''},toastTimer=null,previewTab='input',previewValues={};
let resourceId='',resourceFilter='generate';
const step=()=>project?.steps.find(s=>s.id===selected)||project?.steps[0];
const currentContainer=()=>workspaceProject(workspace,activeProjectId);
function save(){
 if(project&&currentContainer()){const previous=workspaceSkill(workspace,activeProjectId,project.id);if(previous&&JSON.stringify(previous)!==JSON.stringify(project))updateWorkspaceSkill(workspace,activeProjectId,project);}
 if(!storageBlocked){try{localStorage.setItem(WORKSPACE_STORE,JSON.stringify(workspace));storageAvailable=true;startupNotice='';}catch{storageAvailable=false;startupNotice='Changes are available in this tab. Download a backup to keep them.';}}
 $('#save-state').textContent=storageBlocked?'Recovery needed':storageAvailable?'Saved on this device':'Download a backup to keep changes';
}
function notify(text,error=false){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.toggle('error',error);$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function mutate(fn,message,{definitionChange=true}={}){history.push(copy(project));if(history.length>40)history.shift();future=[];fn();if(definitionChange)project.revision++;project.updatedAt=new Date().toISOString();save();render();if(message)notify(message);}
function resetSkillView(){history=[];future=[];selected=project?.steps[0]?.id||'';view='guided';tab='definition';referenceId=project?.references[0]?.id||'';referenceTab='files';packageFile='SKILL.md';previewValues={};previewTab='input';resourceId='';resourceFilter='generate';}
function showProjects(){save();project=null;activeProjectId='';page='projects';resetSkillView();render();}
function openWorkspaceProject(id){save();const container=workspaceProject(workspace,id);if(!container){notify('That project is no longer available.',true);return;}activeProjectId=id;project=null;page='skills';resetSkillView();render();}
function openWorkspaceSkill(projectId,skillId){save();const skill=workspaceSkill(workspace,projectId,skillId);if(!skill){notify('That skill is no longer available.',true);return;}activeProjectId=projectId;project=copy(skill);page='workflow';resetSkillView();render();}
function replaceProject(next,message,destination=activeProjectId){save();addWorkspaceSkill(workspace,destination,next);openWorkspaceSkill(destination,next.id);save();render();if(message)notify(message);}
function backupWorkspaceProject(container){save();const data=workspaceProjectBackup(container);download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),(slugify(container.name)||'project')+'.blueprint.json');notify('Project backup prepared with all its skills and source originals.');}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function button(label,action,extra='',kind=''){return `<button type="button" class="button ${kind}" data-action="${action}" ${extra}>${label}</button>`;}
function field(label,name,value='',{type='text',rows=4,help='',required=false,placeholder=''}={}){return `<label class="field"><span>${label}</span>${type==='textarea'?`<textarea aria-label="${esc(label)}" name="${name}" rows="${rows}" ${required?'required':''} placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input aria-label="${esc(label)}" type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''} placeholder="${esc(placeholder)}">`}${help?`<span class="help">${help}</span>`:''}</label>`;}
function selectField(label,name,value,options){return `<label class="field"><span>${label}</span><select aria-label="${esc(label)}" name="${name}">${options.map(o=>{const item=typeof o==='string'?{value:o,label:o}:o;return `<option value="${esc(item.value)}" ${item.value===value?'selected':''}>${esc(item.label)}</option>`;}).join('')}</select></label>`;}
function selectedStepId(){return step()?.id||'';}
function importNotes(warnings){const retained=warnings.filter(w=>w.startsWith('Source resource retained:'));const legacy=warnings.filter(w=>w.startsWith('Excluded from the Markdown-only skill:'));const resources=[...retained,...legacy];const other=warnings.filter(w=>!resources.includes(w));return (retained.length?`<div class="notice-box">${retained.length} supporting source files are preserved. Python and HTML become English Markdown specifications; data and structural assets stay attached unchanged with structural guides.</div>`:'')+(legacy.length?`<div class="import-note">This older import kept ${legacy.length} resource names only. Re-import the original ZIP to recover their full contents.</div>`:'')+(resources.length?`<details class="facet"><summary>Inspect source resources (${resources.length})</summary><div class="facet-body"><ul>${resources.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div></details>`:'')+other.map(w=>`<div class="import-note">${esc(w)}</div>`).join('');}

function renderResources(){
 const visible=project.resources.filter(r=>r.policy===resourceFilter);const resource=visible.find(r=>r.id===resourceId)||visible[0];resourceId=resource?.id||'';
 const count=policy=>project.resources.filter(r=>r.policy===policy).length;
 $('#content').innerHTML=`<div class="section-heading"><div><h2>Source → reviewable instructions</h2><p>Preserve the source, make its behavior explicit, and attach it to the step that uses it.</p></div><div class="flex"><button class="button quiet" data-reference-tab="files">Markdown references</button><button class="button quiet" data-reference-tab="definitions">Shared rules</button>${button('View source originals','originals')}</div></div><div class="resource-metrics"><div><strong>${count('generate')}</strong><span>English implementation specifications</span></div><div><strong>${count('retain')}</strong><span>Assets retained unchanged</span></div><div><strong>${count('document')}</strong><span>Documentation references</span></div><div><strong>${project.originals.length}</strong><span>Complete source files preserved</span></div></div><div class="flex between resource-toolbar"><div class="segment">${[['generate','Code → English'],['retain','Data & structure'],['document','Documentation']].map(([value,label])=>`<button data-resource-filter="${value}" class="${resourceFilter===value?'active':''}">${label}</button>`).join('')}</div><div class="flex">${button('Attach source files','attach-resources')}${button('Analyze pending sources','analyze-resources','','quiet')}</div></div><div class="page-panel reference-layout"><div class="reference-list resource-list">${visible.map(r=>`<button class="reference-item ${r.id===resource?.id?'active':''}" data-resource="${esc(r.id)}"><strong>${esc(r.sourcePath.split('/').at(-1))}</strong><span class="small">${esc(r.sourcePath)}</span><span class="small">${r.policy==='generate'?r.functionCount+' operations · ':''}${r.reviewed?'Reviewed':'Needs review'}</span></button>`).join('')||'<p class="small">No resources in this category. Import a skill ZIP or attach source files.</p>'}</div><div class="reference-editor stack">${resource?`<div class="flex between"><div><p class="eyebrow">${resource.policy==='generate'?'RUNTIME IMPLEMENTATION':resource.policy==='retain'?'UNCHANGED ASSET + STRUCTURAL GUIDE':'PRESERVED DOCUMENTATION'}</p><h3>${esc(resource.sourcePath)}</h3></div><span class="tag ${resource.reviewed?'':'warning'}">${resource.reviewed?'Reviewed':'English draft'}</span></div><p class="small">${esc(resource.referencePath)}</p><div class="notice-box">${resource.policy==='generate'?'Claude will generate the implementation from this specification at runtime. Review the behavior and acceptance checks before enabling export.':resource.policy==='retain'?'The original file stays in the skill ZIP. Its Markdown guide describes the structure for review.':'The applicable license text is preserved in a Markdown reference.'}</div>${resource.untranslated.length?'<div class="import-note">Translation gaps: '+esc(resource.untranslated.join('; '))+'</div>':''}${resource.policy==='generate'?`<div><h3>Purpose</h3><p>${esc(resource.purpose||'Define the intended behavior.')}</p></div><div class="two-columns"><div class="contract-box"><span class="eyebrow">INPUT CONTRACT</span><p>${esc(resource.inputs)}</p></div><div class="contract-box"><span class="eyebrow">OUTPUT CONTRACT</span><p>${esc(resource.outputs)}</p></div></div><details class="facet"><summary>Read English behavior · ${resource.functionCount} operations</summary><pre class="resource-prose">${esc(resource.behavior)}</pre></details><div><h3>Acceptance checks</h3><p>${esc(resource.checks)}</p></div>`:`<pre class="resource-prose">${esc(resource.structure)}</pre>`}<div><h3>Attached workflow steps</h3><div class="flex">${project.steps.filter(s=>s.resourceIds.includes(resource.id)).map(s=>`<button class="ref-chip" data-resource-step="${esc(s.id)}">${esc(s.title)}</button>`).join('')||'<span class="warning-text">Assign this resource to a step during review.</span>'}</div></div><div class="flex">${button('Edit & review instructions','edit-resource',`data-id="${esc(resource.id)}"`,'primary')}${button('View original source','resource-source',`data-id="${esc(resource.id)}"`,'quiet')}</div><p class="small">English contracts define behavior and tests. Generated source bytes can differ; runtime equivalence still needs testing.</p>`:'<div class="empty"><h3>Keep knowledge and behavior with the process</h3><p>Import a skill ZIP to preserve its complete sources and draft resource instructions.</p></div>'}</div></div>`;
}

function node(s,i,guided=false){const issues=validate(project).errors.filter(e=>e.stepId===s.id);return `<button type="button" class="flow-node ${s.id===selected?'selected':''} ${issues.length?'needs-review':''}" data-step="${esc(s.id)}" aria-pressed="${s.id===selected}" aria-label="Step ${i+1}: ${esc(s.title)}"><span class="node-header"><span class="node-number">${String(i+1).padStart(2,'0')}</span><span>${esc(s.kind)}</span></span><span class="node-title">${esc(s.title)}</span><span class="contract"><span>In</span><span>${esc(inputFor(project,i)||'Define the overall input')}</span></span><span class="contract"><span>Out</span><span>${esc(s.output||'Define this output')}</span></span>${guided?`<span class="small">${esc(s.job)}</span>`:''}<span class="node-footer"><span>${s.facets.length} facets inside</span><span class="${issues.length?'warning-text':''}">${!s.reviewed?'Review import':issues.length?'Review definition':'↗'}</span></span></button>`;}
function renderWorkflow(){const s=step(),index=project.steps.indexOf(s),checks=validate(project);let cards='';if(view==='guided'&&s){cards=`<div class="guide-nav"><span class="small">Step ${index+1} of ${project.steps.length}</span>${button('See whole flow','flow','','quiet')}</div>${node(s,index,true)}<div class="guide-nav">${button('← Previous step','previous',index===0?'disabled':'')}${button('Next step →','next',index===project.steps.length-1?'disabled':'','primary')}</div>`;}else{cards=project.steps.map((st,i)=>node(st,i)).join('');if(view==='flow'&&project.steps.length)cards+=`<button type="button" class="flow-node terminal" data-action="preview"><span class="eyebrow">THE FINAL OUTPUT</span><span class="node-title">${esc(project.steps.at(-1).output||'Define the result')}</span><span class="small">${esc(project.outcome||'Describe the intended outcome')}</span><span class="node-footer"><span>Preview the screens</span><span>↗</span></span></button>`;}
 $('#content').innerHTML=`<div class="workbench"><div class="workflow-toolbar"><div class="segment" aria-label="Workflow view">${['guided','list','flow'].map(v=>`<button type="button" data-view="${v}" class="${view===v?'active':''}" aria-pressed="${view===v}">${v==='guided'?'Step by step':v==='flow'?'Canvas':'List'}</button>`).join('')}</div><div class="flex"><button type="button" class="review-pill ${checks.errors.length?'':'clear'}" data-page="package">${checks.errors.length?`${checks.errors.length} ${checks.errors.length===1?'decision':'decisions'} to resolve`:'Structure aligned'}</button>${button('▷ Preview screens','preview','','quiet')}</div></div><div class="workspace"><section class="stage" aria-label="Workflow diagram"><div class="canvas-bar"><span>${project.steps.length} connected steps · one input → one output</span>${button('＋ Add step','add-step','','quiet')}</div><div class="canvas ${view}" id="canvas">${view==='flow'?'<svg class="edges" aria-hidden="true"></svg>':''}${cards||'<div class="empty"><h3>Start with a meaningful transformation</h3><p class="small">What comes in, what should happen, and what comes out?</p>'+button('Add your first step','add-step','','primary')+'</div>'}</div><div class="resources-bar"><span>Shared references</span>${project.references.map(r=>`<button class="ref-chip" data-reference="${esc(r.id)}">${esc(r.path.split('/').at(-1))}</button>`).join('')}${button(project.resources.length+' resources','resources','','quiet small-button')}${button('Manage rules','definitions','','quiet small-button')}</div></section><aside class="inspector" aria-label="Selected workflow step">${renderInspector()}</aside></div><footer class="workbench-footer"><span class="draft-label">Draft · revision ${project.revision}</span><span>Edits propagate into linked inputs and generated instructions.</span><span>English instructions + supporting assets</span></footer></div>`;
 if(project.steps.some(st=>!st.reviewed))$('#content .canvas-bar>span').textContent=project.steps.length+' proposed sections · verify boundaries and order';
 if(view==='flow'){const cards=[...$('#canvas').querySelectorAll('.flow-node')];cards.forEach((card,i)=>{const row=Math.floor(i/2);card.style.gridColumn=String(row%2===0?i%2+1:2-i%2);card.style.gridRow=String(row+1);});requestAnimationFrame(drawEdges);}
}
function renderInspector(){const s=step();if(!s)return '<div class="empty"><p class="small">Select a step to define its behavior.</p></div>';const index=project.steps.indexOf(s);let body='';
 if(tab==='definition')body=`<div class="contract-box"><span class="eyebrow">INPUT</span><strong>${esc(inputFor(project,index)||'Define the overall input')}</strong>${index?`<button class="inline-link" data-step="${esc(project.steps[index-1].id)}">From step ${index} · ${esc(project.steps[index-1].title)}</button>`:'<span class="small">Supplied through the input screen</span>'}</div><div><h3>What this step should do</h3><p class="job-text">${esc(s.job||'Describe the transformation and its success conditions.')}</p></div><div class="contract-box"><span class="eyebrow">OUTPUT</span><strong>${esc(s.output||'Define this output')}</strong><span class="small">${index<project.steps.length-1?'Used by step '+(index+2)+' · '+esc(project.steps[index+1].title):'Final result of this process'}</span></div>${s.references.length?'<div><h3>Linked references</h3><div class="flex">'+s.references.map(path=>{const r=project.references.find(x=>x.path===path);return `<button class="ref-chip" data-reference="${esc(r?.id||'')}">${esc(path)}</button>`;}).join('')+'</div></div>':''}${s.resourceIds.length?`<div><h3>Supporting resources</h3><p class="small">${s.resourceIds.length} specifications and assets attached to this step.</p>${button('Review attached resources','step-resources','','quiet small-button')}</div>`:''}${s.source?`<div class="source-callout"><span>Imported from ${esc(s.source.path)}${s.source.start?' · lines '+s.source.start+'–'+(s.source.end||'?'):''}</span>${button('View original instructions','source','','quiet small-button')}${!s.reviewed?button('Confirm this proposed step','approve','','small-button'):''}</div>`:''}<div class="flex">${button('Edit step','edit-step','','primary')}${button('Inside this step →','facets','','quiet')}</div>`;
 else if(tab==='facets')body=`<p class="small">Functions, references, rules, and exceptions stay inside this input → output boundary.</p>${s.facets.map(f=>{const def=project.definitions.find(d=>d.id===f.definitionId);return `<details class="facet" open><summary>${esc(f.title)}</summary><div class="facet-body"><span class="tag">${esc(f.type)}</span><span>${esc(f.instructions)}</span>${f.type==='Tool'?`<span>MCP: ${esc(f.connection)} · ${esc(f.operation)}</span>`:''}${def?`<span class="${f.override&&f.override!==def.value?'warning-text':''}">${esc(def.name)}: ${esc(definitionValue(project,f))}${f.override?' · local override':' · shared value'}</span>`:''}<div class="flex">${button('Edit facet','edit-facet',`data-id="${esc(f.id)}"`,'quiet small-button')}${f.override?button('Use shared value','clear-override',`data-id="${esc(f.id)}"`,'small-button'):''}</div></div></details>`;}).join('')}${button('＋ Add a facet','add-facet')}`;
 else body=`<div><h3>Example input</h3><p class="job-text">${esc(s.exampleInput||'Add an example of what this step receives.')}</p></div><div class="contract-box"><span class="eyebrow">EXPECTED OUTPUT</span><p class="job-text">${esc(s.exampleOutput||'Describe the expected result.')}</p></div>${button('Edit examples','edit-step')}`;
 return `<div class="inspector-heading"><p class="eyebrow">STEP ${String(index+1).padStart(2,'0')} / ${esc(s.kind)}</p><h2>${esc(s.title)}</h2><span class="small">${s.facets.length} facets · ${esc(s.output)}</span></div><div class="inspector-tabs" aria-label="Step details">${['definition','facets','example'].map(t=>`<button data-tab="${t}" class="${tab===t?'active':''}" aria-pressed="${tab===t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div class="inspector-body">${body}</div><div class="inspector-footer">${button('↑ Move','move-up',index===0?'disabled':'','quiet small-button')}${button('↓ Move','move-down',index===project.steps.length-1?'disabled':'','quiet small-button')}${button('Remove step','remove-step','','quiet danger small-button')}</div>`;
}
function drawEdges(){const canvas=$('#canvas'),svg=canvas?.querySelector('.edges');if(!svg)return;const box=canvas.getBoundingClientRect(),nodes=[...canvas.querySelectorAll('.flow-node')];svg.setAttribute('viewBox',`0 0 ${box.width} ${box.height}`);svg.innerHTML='<defs><marker id="flow-arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M1 1 L7 4 L1 7" fill="none" stroke="#9ba9bd" stroke-width="1.4"/></marker></defs>';for(let i=0;i<nodes.length-1;i++){const a=nodes[i].getBoundingClientRect(),b=nodes[i+1].getBoundingClientRect();let path;if(Math.abs(a.top-b.top)<6){const right=b.left>a.left;path=`M ${(right?a.right:a.left)-box.left} ${a.top-box.top+a.height/2} L ${(right?b.left:b.right)-box.left} ${b.top-box.top+b.height/2}`;}else{const x1=a.left-box.left+a.width/2,x2=b.left-box.left+b.width/2,y1=a.bottom-box.top,y2=b.top-box.top,mid=(y1+y2)/2;path=`M ${x1} ${y1} V ${mid} H ${x2} V ${y2}`;}svg.innerHTML+=`<path d="${path}" fill="none" stroke="#9ba9bd" stroke-width="1.4" stroke-linejoin="round" marker-end="url(#flow-arrow)"/>`;}}

function renderReferences(){if(referenceTab==='resources'){renderResources();return;}const ref=project.references.find(r=>r.id===referenceId)||project.references[0];$('#content').innerHTML=`<div class="section-heading"><div><h2>References & shared rules</h2><p>Maintain definitions once, then connect them to the steps that use them.</p></div><div class="segment"><button data-reference-tab="resources">Resources (${project.resources.length})</button><button class="${referenceTab==='files'?'active':''}" data-reference-tab="files">Markdown references</button><button class="${referenceTab==='definitions'?'active':''}" data-reference-tab="definitions">Shared definitions</button></div></div>${referenceTab==='files'?`<div class="page-panel reference-layout"><div class="reference-list">${button('＋ New reference','add-reference','','primary')}${button('Import Markdown','import-reference')}${project.references.map(r=>`<button class="reference-item ${r.id===ref?.id?'active':''}" data-reference="${esc(r.id)}"><strong>${esc(r.path.split('/').at(-1))}</strong><span class="small">${esc(r.path)}</span></button>`).join('')}</div><div class="reference-editor stack">${ref?`<div class="flex between"><div><h3>${esc(ref.path.split('/').at(-1))}</h3><span class="small">${project.steps.filter(s=>s.references.includes(ref.path)).length} linked steps</span></div><div class="flex">${button('Edit reference','edit-reference',`data-id="${esc(ref.id)}"`)}${button('Remove','remove-reference',`data-id="${esc(ref.id)}"`,'quiet danger')}</div></div><pre>${esc(ref.content)}</pre>`:'<div class="empty"><h3>Add the knowledge this process relies on</h3><p class="small">A processing guide, configuration reference, or shared definition can stay in Markdown.</p></div>'}</div></div>`:`<div class="page-panel"><div class="section-heading"><div><h3>One authoritative value</h3><p>Facets read the shared value. Conflicting local overrides appear in review.</p></div>${button('＋ Add definition','add-definition','','primary')}</div>${project.definitions.map(d=>`<div class="rule-card"><div><h3>${esc(d.name)}</h3><p class="rule-value">${esc(d.value)}</p><p class="small">${esc(d.intent||'')}</p><p class="small">${project.steps.flatMap(s=>s.facets).filter(f=>f.definitionId===d.id).length} linked facets</p></div><div class="flex">${button('Edit','edit-definition',`data-id="${esc(d.id)}"`)}${button('Remove','remove-definition',`data-id="${esc(d.id)}"`,'quiet danger')}</div></div>`).join('')||'<div class="empty"><p class="small">Create a shared definition for a rule used by multiple steps.</p></div>'}</div>`}`;}
function inputDefault(f){return project.definitions.find(d=>d.id===f.definitionId)?.value||f.defaultValue||'';}
function renderScreens(){const fields=project.screens.input,columns=project.screens.output;$('#content').innerHTML=`<div class="section-heading"><div><h2>Input & output</h2><p>Describe the screens the skill should present. Keep field order and output shape explicit.</p></div><div class="flex">${button('Presentation rules','screen-rules')}${button('▷ Preview screens','preview','','primary')}</div></div><div class="two-columns"><section class="page-panel"><div class="flex between"><div><p class="eyebrow">THE STARTING POINT</p><h3>Input screen</h3></div>${button('＋ Add field','add-field')}</div><div class="field-list">${fields.map((f,i)=>`<div class="field-row"><span class="node-number">${i+1}</span><div class="field-row-label"><strong>${esc(f.label)}</strong><div class="small">${esc(f.type)} · ${f.required?'Required':'Optional'}${f.definitionId?' · Shared value':''}</div></div>${button('Edit','edit-field',`data-id="${esc(f.id)}"`,'quiet small-button')}</div>`).join('')||'<p class="small">No input fields defined yet.</p>'}</div><p class="small">These instructions are included in the exported screen reference.</p></section><section class="page-panel stack"><div class="flex between"><div><p class="eyebrow">THE INTENDED RESULT</p><h3>Output screen</h3></div>${button('Edit columns','columns')}</div><div class="flex">${columns.map((c,i)=>`<span class="tag">${i+1} · ${esc(c)}</span>`).join('')||'<p class="small">Define the output columns.</p>'}</div><p class="small">${esc(project.screens.instructions||'Add presentation rules for the final output.')}</p><div class="flex between"><h4>Example rows</h4>${button('＋ Add example row','add-row','','quiet')}</div>${project.screens.sampleRows.map((row,i)=>`<div class="field-row"><div class="field-row-label">${esc(columns.map(c=>row[c]||'—').join(' · '))}</div>${button('Edit','edit-row',`data-index="${i}"`,'quiet small-button')}</div>`).join('')||'<p class="small">Add sample results to inspect the presentation.</p>'}<span class="sample-label">Preview data · no live retrieval</span></section></div>`;}
function renderScenarios(){const scenarios=project.scenarios;$('#content').innerHTML=`<div class="section-heading"><div><h2>Test scenarios</h2><p>Define expected behavior, test the exported skill in Claude, then record what happened.</p></div>${button('＋ Add scenario','add-scenario','','primary')}</div><section class="page-panel">${scenarios.map(s=>{const current=s.testedRevision===project.revision;return `<article class="scenario-card"><div><h3>${esc(s.name)}</h3><div class="flex" style="margin-top:9px"><span class="tag ${s.status==='Fail'?'warning':''}">${s.status==='Not tested'?'Not tested':current?esc(s.status):'Needs recheck'}</span><span class="small">${s.testedRevision?'Tested r'+s.testedRevision:'Current r'+project.revision}</span></div>${s.observations?`<p class="small" style="margin-top:10px">${esc(s.observations)}</p>`:''}</div><div class="scenario-copy"><div><h4>Input</h4><p class="small">${esc(s.input)}</p></div><div><h4>Expected result</h4><p class="small">${esc(s.expected)}</p></div></div><div class="flex">${button('Record result','record-test',`data-id="${esc(s.id)}"`)}${button('Edit','edit-scenario',`data-id="${esc(s.id)}"`,'quiet')}</div></article>`;}).join('')||'<div class="empty"><h3>Start with an example that matters</h3><p class="small">Include the normal path and exceptions such as missing inputs or unavailable tools.</p></div>'}</section><div class="notice-box" style="margin-top:17px">Results are recorded by the user after testing. This prototype does not execute a model or connect to external tools.</div>`;}
function renderIndependentReview(){const state=independentReviewState(project);if(!state.required)return '';const report=project.independentReview?.report;return `<div class="notice-box stack"><div class="flex between"><div><h3>Independent adversarial review · ${esc(state.status)}</h3><p class="small">A separate reviewer must challenge the original sources and converted draft. Every content change invalidates the prior review.</p></div><div class="flex">${button('Prepare review packet','review-packet')}${button('Load reviewer report','load-review-report')}</div></div>${report?`<p>${esc(report.summary)}</p><p class="small">Reviewer: ${esc(report.reviewer.identity)} · ${esc(report.outcome)} · licensing ${esc(report.licensing.status)}</p>${report.findings.map(f=>`<p class="small">${esc(f.severity)} / ${esc(f.status)} · ${esc(f.description)} · ${esc(f.location)}</p>`).join('')}`:'<p class="small">Review has not been performed. Local checks and resource approval boxes cannot complete it.</p>'}${sourceTriage(project).map(f=>`<p class="small">Static indicator · ${esc(f.path)}: ${esc(f.message)}</p>`).join('')}<p class="small">Reviewer identity is declared, not authenticated, in this local prototype. No model review is automatically executed.</p></div>`;}
function renderPackage(){const checks=validate(project),files=compile(project,{allowInvalid:true});if(!Object.hasOwn(files,packageFile))packageFile='SKILL.md';$('#content').innerHTML=`<div class="section-heading"><div><h2>Review the skill package</h2><p>Resolve definition gaps, then export the skill for testing in Claude.</p></div>${button('Download skill ZIP','export',checks.errors.length?'disabled':'','primary')}</div><section class="page-panel">${renderIndependentReview()}<div class="review-summary ${checks.errors.length?'blocked':''}"><span style="font-size:20px">${checks.errors.length?'!':'✓'}</span><div><h3>${checks.errors.length?checks.errors.length+' '+(checks.errors.length===1?'decision':'decisions')+' before export':'Ready to export for testing'}</h3><p class="small">${checks.errors.length?'Make the intended behavior explicit.':'The structural checks passed. Runtime tests remain separate.'}</p></div></div>${checks.errors.map((issue,i)=>`<div class="issue-row"><p>${esc(issue.message)}</p>${button('Review →','review-issue',`data-index="${i}"`,'quiet small-button')}</div>`).join('')}<ul class="warning-list">${checks.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>${project.importWarnings.length?button('Review import notes','import-notes','','quiet'):''}<div class="package-layout"><div class="stack"><div><p class="eyebrow">${esc(project.slug||'your-skill')}/</p><div class="file-tree">${Object.keys(files).map(path=>`<button data-package-file="${esc(path)}" class="${path===packageFile?'active':''}">${esc(path)}</button>`).join('')}</div></div><p class="small">Python and HTML are represented by English Markdown specifications. Data and structural assets stay unchanged. Project backups preserve complete source originals.</p>${project.originals.length?button('View source originals','originals'):''}${button('Back up this skill','save-skill')}</div><pre class="code-preview" aria-label="Generated ${esc(packageFile)}">${esc(files[packageFile] instanceof Uint8Array?assetPreview(packageFile,files[packageFile]):files[packageFile])}</pre></div></section>`;}
function render(){
 const container=currentContainer();if(page==='skills'&&!container)page='projects';
 const editor=Boolean(project&&container&&!['projects','skills'].includes(page));
 document.querySelectorAll('.editor-only').forEach(el=>el.hidden=!editor);
 document.querySelectorAll('.project-only').forEach(el=>el.hidden=!container);
 document.querySelectorAll('.directory-only').forEach(el=>el.hidden=page!=='projects');
 $('#project-title').textContent=page==='projects'?'Projects':page==='skills'?container.name:project.title;
 $('#project-description').textContent=page==='projects'?'Keep related skills together. Open a project or start a new one.':page==='skills'?(container.description||'Choose a skill to edit, or add a fresh or imported skill.'):(project.purpose||'Build a process one meaningful transformation at a time.');
 $('#project-eyebrow').textContent=page==='projects'?'YOUR WORKSPACE':page==='skills'?'PROJECT / SKILLS':'SKILL / '+({workflow:'WORKFLOW',references:'KNOWLEDGE',screens:'PRESENTATION',scenarios:'VALIDATION',package:'SKILL PACKAGE'}[page]);
 $('#project-actions').innerHTML=page==='projects'?button('＋ Create project','create-workspace-project','','primary')+button('Restore project','restore-project'):page==='skills'?button('＋ Add skill','add-skill','','primary')+button('Edit project','edit-workspace-project',`data-id="${esc(container.id)}"`):button('Edit brief','project')+'<button class="button primary" data-page="package">Review & export ↗</button>';
 $('#breadcrumbs').innerHTML=page==='projects'?'':button('Projects','projects','','quiet')+'<span aria-hidden="true">›</span>'+(editor?button(esc(container.name),'project-skills','','quiet')+'<span aria-hidden="true">›</span><span>'+esc(project.title)+'</span>':'<span>'+esc(container.name)+'</span>');
 $('#breadcrumbs').hidden=page==='projects';
 $('#workspace-notice').hidden=!startupNotice;$('#workspace-notice').innerHTML=startupNotice?'<p>'+esc(startupNotice)+'</p>'+(storageBlocked?'<div class="flex">'+button('Download recovery copy','download-recovery')+button('Start a new workspace','reset-workspace','','quiet')+'</div>':''):'';
 document.querySelectorAll('.nav-item').forEach(b=>{const active=b.dataset.page===page;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 $('#nav-issues').textContent=editor?(validate(project).errors.length||''):'';
 document.querySelector('[data-action="undo"]').disabled=!editor||!history.length;document.querySelector('[data-action="redo"]').disabled=!editor||!future.length;
 document.querySelector('.top-actions [data-action="save-project"]').textContent=container?'Back up project':'Back up projects';
 if(page==='projects'){ $('#content').innerHTML=projectDirectoryMarkup(workspace);return; }
 if(page==='skills'){ $('#content').innerHTML=skillDirectoryMarkup(container);return; }
 if(project.steps.length&&!project.steps.some(s=>s.id===selected))selected=project.steps[0].id;
 ({workflow:renderWorkflow,references:renderReferences,screens:renderScreens,scenarios:renderScenarios,package:renderPackage}[page])();
}

function openDialog(mode,{id='',index=-1}={}){dialogState={mode,id,index};const s=step();let title='',eyebrow='SKILL AUTHORING',body='',submit='Save',extra='',help='Changes update the editable process and its generated instructions.';
 if(mode==='create-workspace-project'||mode==='edit-workspace-project'){const container=mode==='edit-workspace-project'?workspaceProject(workspace,id):{name:'',description:''};if(!container){dialogState=null;return;}title=mode==='create-workspace-project'?'Create a project':'Edit project';eyebrow='PROJECT ORGANIZATION';body=field('Project name','projectName',container.name,{required:true,placeholder:'What are these skills for?'})+field('Description (optional)','projectDescription',container.description,{type:'textarea',rows:3});submit=mode==='create-workspace-project'?'Create project':'Save project';help='A project groups related skills. Add or import skills after creating it.';}
 else if(mode==='add-skill'){if(!currentContainer()){dialogState=null;return;}title='How would you like to add a skill?';eyebrow=currentContainer().name;body='<div class="skill-choice-grid"><button type="button" class="skill-choice" data-action="new"><span class="directory-icon">＋</span><strong>Create a fresh skill</strong><span>Start with a name, then define its process step by step.</span></button><button type="button" class="skill-choice" data-action="import"><span class="directory-icon">↥</span><strong>Import an existing skill</strong><span>Bring in SKILL.md or a ZIP, then review and refine the workflow.</span></button></div>';submit='';help='The new skill will be added to this project. Your other skills stay in place.';}
 else if(mode==='new'){if(!currentContainer()){dialogState=null;return;}title='Create a fresh skill';eyebrow='ADD A SKILL / '+currentContainer().name;body=field('Skill title','title','',{required:true})+field('Skill name','slug','',{required:true,help:'Lowercase words separated by hyphens. This becomes the export folder name.'})+field('What should this skill help you do? (optional)','description','',{type:'textarea',rows:3});submit='Create skill';help='Define inputs, outputs, instructions, and the workflow in the skill editor.';}
 else if(mode==='reset-workspace'){title='Start a new workspace?';eyebrow='SAVED DATA RECOVERY';body='<p>The unreadable saved workspace will be replaced when you create new projects. Download the recovery copy first if you need to keep it.</p>'+button('Download recovery copy','download-recovery')+'<label class="check-row"><input type="checkbox" name="confirmReset" required>I have kept a recovery copy or do not need the earlier data.</label>';submit='Start new workspace';help='';}
 else if(mode==='project'){const p=project;title='The skill brief';body=field('Skill title','title',p.title,{required:true})+field('Skill name','slug',p.slug,{required:true,help:'Lowercase words separated by hyphens. This becomes the skill folder name.'})+field('What does it do, and when should it be used?','description',p.description,{type:'textarea',rows:3,required:true})+field('Purpose','purpose',p.purpose,{type:'textarea',rows:2})+'<div class="field-grid">'+field('Overall input','input',p.input,{required:true})+field('Final output / completion condition','outcome',p.outcome,{type:'textarea',rows:2,required:true})+'</div>'+field('Instructions used across the process','instructions',p.instructions,{type:'textarea',rows:3})+`<details class="facet"><summary>Additional skill metadata</summary><div class="facet-body">${field('Optional frontmatter fields','extraFrontmatter',p.extraFrontmatter,{type:'textarea',rows:4,help:'Keep license and compatibility information intact. Name and description are managed above.'})}</div></details>`;}
 else if(mode==='edit-step'||mode==='add-step'){const current=mode==='add-step'?newStep(''):s;title=mode==='add-step'?'Add a meaningful step':'Define this step';eyebrow='ONE INPUT → ONE OUTPUT';body=field('What should this step accomplish?','title',current.title,{required:true})+selectField('Step type','kind',current.kind,['Input','Select','Retrieve','Transform','Decision','Output','Process'])+`<div class="contract-box"><span class="eyebrow">INPUT ${mode==='add-step'?'FROM THE SELECTED STEP':''}</span><strong>${esc(mode==='add-step'?(s?.output||project.input):inputFor(project,project.steps.indexOf(s)))}</strong></div>`+field('What should happen?','job',current.job,{type:'textarea',rows:5,required:true})+field('What should it produce?','output',current.output,{required:true})+'<div class="field-grid">'+field('Example input','exampleInput',current.exampleInput,{type:'textarea',rows:3})+field('Expected output','exampleOutput',current.exampleOutput,{type:'textarea',rows:3})+'</div>'+`<div class="stack"><h4>Linked references</h4>${project.references.map(r=>`<label class="check-row"><input type="checkbox" name="references" value="${esc(r.path)}" ${current.references.includes(r.path)?'checked':''}>${esc(r.path)}</label>`).join('')||'<p class="small">Add Markdown resources in References & rules.</p>'}</div>`+`<div class="stack"><h4>Supporting resources</h4>${project.resources.map(r=>`<label class="check-row"><input type="checkbox" name="resourceIds" value="${esc(r.id)}" ${current.resourceIds.includes(r.id)?'checked':''}>${esc(r.sourcePath)} · ${r.policy==='generate'?'English specification':'Retained asset or documentation'}</label>`).join('')||'<p class="small">Import or attach supporting sources in Resources.</p>'}</div>`;if(current.source&&!current.reviewed)body+='<label class="check-row"><input type="checkbox" name="reviewed">I have reviewed the source mapping and confirmed this step.</label>';submit=mode==='add-step'?'Add step':'Save step';}
 else if(mode==='add-facet'||mode==='edit-facet'){const f=mode==='edit-facet'?s.facets.find(x=>x.id===id):{title:'',type:'Instruction',instructions:'',definitionId:'',override:'',connection:'',operation:''};title=mode==='add-facet'?'Add a facet inside this step':'Define this facet';eyebrow=s.title;body=field('Facet name','title',f.title,{required:true})+selectField('Facet type','type',f.type,['Instruction','Reference','Tool','Business rule','Decision','Exception'])+field('What should happen?','instructions',f.instructions,{type:'textarea',rows:4,required:true})+'<div class="field-grid">'+field('MCP connection (for a tool facet)','connection',f.connection,{help:'A configured tool name, never a password or access token.'})+field('MCP operation (for a tool facet)','operation',f.operation)+'</div>'+selectField('Use a shared definition','definitionId',f.definitionId,[{value:'',label:'No shared definition'},...project.definitions.map(d=>({value:d.id,label:d.name+' · '+d.value}))])+field('Local override (leave empty to follow the shared value)','override',f.override,{help:'A conflicting override must be resolved before export.'});if(mode==='edit-facet')extra=button('Remove facet','remove-facet',`data-id="${esc(id)}"`,'quiet danger');}
 else if(mode==='edit-resource'){const r=project.resources.find(x=>x.id===id);title='Review resource instructions';eyebrow=r.sourcePath;body=`<div class="notice-box">${r.policy==='generate'?'Review the English behavior, interfaces and checks. Original code stays in the separate source archive.':'Keep the original asset unchanged and review its structural guide.'}</div>`+(r.policy==='generate'?CONTRACT_FIELDS.map(key=>field(key[0].toUpperCase()+key.slice(1),key,r[key],{type:'textarea',rows:key==='behavior'?14:3,required:true})).join(''):field('Structure / documentation','structure',r.structure,{type:'textarea',rows:12,required:true}))+field('Runtime dependencies (one resource path per line)','dependencies',r.dependencies.join('\n'),{type:'textarea',rows:3})+field('Unresolved translation gaps (one per line)','untranslated',r.untranslated.join('\n'),{type:'textarea',rows:2,help:'Clear a gap only after its behavior is fully specified.'})+`<div class="stack"><h4>Used by workflow steps</h4>${project.steps.map(s=>`<label class="check-row"><input type="checkbox" name="resourceSteps" value="${esc(s.id)}" ${s.resourceIds.includes(r.id)?'checked':''}>${esc(s.title)}</label>`).join('')}</div><label class="check-row"><input type="checkbox" name="resourceReviewed" ${r.reviewed?'checked':''}>I reviewed these instructions and their acceptance checks.</label>`;submit='Save resource review';}
 else if(mode==='add-reference'||mode==='edit-reference'){const r=mode==='edit-reference'?project.references.find(x=>x.id===id):{path:'references/',content:''};title=mode==='add-reference'?'Add a Markdown reference':'Edit the reference';body=field('Relative file path','path',r.path,{required:true,help:'For example, references/processing-rules.md. Linked steps follow path changes.'})+field('Reference instructions','content',r.content,{type:'textarea',rows:14,required:true});}
 else if(mode==='add-definition'||mode==='edit-definition'){const d=mode==='edit-definition'?project.definitions.find(x=>x.id===id):{name:'',value:'',intent:'',runtimeInput:''};title='Shared definition';body=field('Definition name','name',d.name,{required:true})+field('Fixed value or default','value',d.value,{required:true})+selectField('At runtime, read the value from','runtimeInput',d.runtimeInput||'',[{value:'',label:'Use the fixed value'},...project.screens.input.map(f=>({value:f.label,label:'Input screen · '+f.label}))])+field('Why and where should this value be used?','intent',d.intent,{type:'textarea',rows:3});help='Linked facets follow the runtime input when one is bound; otherwise they use the fixed value.';}
 else if(mode==='add-field'||mode==='edit-field'){const f=mode==='edit-field'?project.screens.input.find(x=>x.id===id):{label:'',type:'Text',required:true,defaultValue:'',options:[],definitionId:''};title='Input screen field';body=field('Field label','label',f.label,{required:true})+selectField('Field type','type',f.type,['Text','Select','Date','Number'])+field('Default value','defaultValue',f.defaultValue)+field('Choices (one per line, for a Select field)','options',f.options.join('\n'),{type:'textarea',rows:3})+selectField('Default follows a shared definition','definitionId',f.definitionId||'',[{value:'',label:'Use the field’s default'},...project.definitions.map(d=>({value:d.id,label:d.name+' · '+d.value}))])+`<label class="check-row"><input type="checkbox" name="required" ${f.required?'checked':''}>Required input</label>`;if(mode==='edit-field')extra=button('Remove field','remove-field',`data-id="${esc(id)}"`,'quiet danger')+button('Move earlier','move-field',`data-id="${esc(id)}"`,'quiet');}
 else if(mode==='columns'){title='Output column order';body=field('Columns (one per line)','columns',project.screens.output.join('\n'),{type:'textarea',rows:7,required:true});help='Order is preserved in the screen preview and exported instructions.';}
 else if(mode==='screen-rules'){title='Screen presentation rules';body=field('How should the input and output be presented?','instructions',project.screens.instructions,{type:'textarea',rows:9});}
 else if(mode==='add-row'||mode==='edit-row'){title='Example output row';if(!project.screens.output.length){notify('Define output columns first.',true);dialogState=null;return;}const row=mode==='edit-row'?project.screens.sampleRows[index]:{};body='<div class="field-grid">'+project.screens.output.map((c,i)=>field(esc(c),'column-'+i,row[c]||'')).join('')+'</div>';help='Sample data for inspecting the screen; no calculation or live retrieval.';if(mode==='edit-row')extra=button('Remove row','remove-row',`data-index="${index}"`,'quiet danger');}
 else if(mode==='add-scenario'||mode==='edit-scenario'){const t=mode==='edit-scenario'?project.scenarios.find(x=>x.id===id):{name:'',input:'',expected:''};title='Describe a test scenario';body=field('Scenario name','name',t.name,{required:true})+field('Input and conditions','input',t.input,{type:'textarea',rows:4,required:true})+field('Expected result','expected',t.expected,{type:'textarea',rows:4,required:true});if(mode==='edit-scenario')extra=button('Remove scenario','remove-scenario',`data-id="${esc(id)}"`,'quiet danger');}
 else if(mode==='record-test'){const t=project.scenarios.find(x=>x.id===id);title='Record the actual test result';eyebrow=t.name;body=`<div class="notice-box">Current revision: ${project.revision}. Run this scenario against the exported skill in Claude, then record the observed behavior.</div>`+selectField('Result','status',t.status,['Not tested','Pass','Fail','Needs review'])+field('What happened?','observations',t.observations||'',{type:'textarea',rows:6,required:true});help='This records your observation. It does not run or verify Claude.';submit='Record result';}
 else if(mode==='import'){if(!currentContainer()){dialogState=null;return;}importDestination=activeProjectId;eyebrow=currentContainer().name;title='Bring an existing skill into the builder';body=`<div class="import-drop"><h3>SKILL.md or a skill ZIP</h3><p class="small">Import the full skill, draft English specifications for its code, and retain its data assets.</p>${button('Choose a file','choose-import','','primary')}<p class="small">One skill at a time · up to 8 MB</p></div>`+field('Or paste the contents of SKILL.md','markdown','',{type:'textarea',rows:8,placeholder:'---\nname: your-skill\ndescription: What it does and when to use it\n---\n\n# Your skill'});submit='Review pasted skill';help='Imports are analyzed locally. Heading-based proposals require your review.';}
 else if(mode==='import-review'){title='Review the proposed workflow';eyebrow=workspaceProject(workspace,pendingImportProjectId)?.name||'IMPORT REVIEW';body=`<div class="notice-box">${pendingImport.steps.some(s=>!s.reviewed)?'The headings suggest these steps. Input and output boundaries still need your review.':'This package was generated by Skill Blueprint Studio. Its step structure and facets have been restored.'}</div><div class="import-list">${pendingImport.steps.map((st,i)=>`<div class="import-row"><span class="node-number">${i+1}</span><div><strong>${esc(st.title)}</strong><p class="small">${esc(st.source?.path||'SKILL.md')}${st.source?.start?' · lines '+st.source.start+'–'+st.source.end:''}</p><p class="small">${esc(st.output||'Output needs definition')}</p></div><span class="tag ${st.reviewed?'':'warning'}">${st.reviewed?'Restored':'Proposed'}</span></div>`).join('')}</div><p class="small">${pendingImport.references.length} Markdown references · ${pendingImport.originals.length} source entries retained</p>${importNotes(pendingImport.importWarnings)}`;submit='Add skill & open editor';help='The imported skill is added to this project. Other skills are preserved.';}
 else if(mode==='import-notes'){title='Review the import notes';body=importNotes(project.importWarnings)+`<label class="check-row"><input type="checkbox" name="acknowledged" ${project.warningsAcknowledged?'checked':''}>I reviewed the source preservation, resource dispositions, and proposed workflow.</label>`;submit='Save review';help='Unreviewed steps and missing file dependencies remain separate checks.';}
 else if(mode==='source'){title='Original instructions';eyebrow=s.source?.path||'SOURCE';body=`<p class="small">${s.source?.start?'Source lines '+s.source.start+'–'+s.source.end: 'Retained at import'} · stored separately from edited instructions</p><pre class="original-file">${esc(s.source?.text||'')}</pre>`;submit='';help='';}
 else if(mode==='originals'){title='Complete source originals';body='<p class="small">Imported files are preserved for analysis, including code, schemas, templates, and licenses. The generated skill package uses the reviewed instructions and follows the separate export rule.</p>'+button('Download original source bundle','download-originals','','primary')+project.originals.map(o=>`<details class="facet"><summary>${esc(o.path)} · ${esc(o.kind||resourceKind(o.path))}</summary><div class="facet-body"><span>${o.encoding==='unavailable'?'Older import: re-import the original ZIP to recover this file.':o.size!==undefined?o.size+' source bytes':'Original source text'}</span>${o.encoding==='base64'?'<p>Binary resource preserved byte for byte.</p>':`<pre class="original-file">${esc(o.content)}</pre>`}${button('Download source file','download-source',`data-path="${esc(o.path)}" ${o.encoding==='unavailable'?'disabled':''}`,'small-button')}</div></details>`).join('');submit='';help='Source bundles preserve original file contents; they are separate from the generated skill ZIP.';}
 else if(mode==='remove-step'){title='Remove this step?';body=`<p>${esc(s.title)} will be removed. The following input will reconnect to the previous output.</p><p class="small">Undo restores the step and its facets.</p>`;submit='Remove step';}
 else if(mode==='preview'){title='Preview input & output';eyebrow='SAMPLE PRESENTATION';body=previewBody();submit='';help='Illustrative presentation based on your screen definitions.';}
 $('#dialog-title').textContent=title;$('#dialog-eyebrow').textContent=eyebrow;$('#dialog-body').innerHTML=body+'<div id="dialog-error" class="dialog-error" role="alert" hidden></div>';$('#dialog-footer').innerHTML=(help?'<span class="small">'+help+'</span>':'')+extra+button(submit?'Cancel':'Close','close','','quiet')+(submit?`<button class="button primary" type="submit">${submit}</button>`:'');if(!$('#dialog').open)$('#dialog').showModal();
}
function closeDialog(){if(dialogState?.mode==='import'||dialogState?.mode==='import-review'){pendingImport=null;pendingImportProjectId='';importRequestToken++;}if($('#dialog').open)$('#dialog').close();dialogState=null;}
function dialogError(message){const el=$('#dialog-error');if(el){el.hidden=false;el.textContent=message;}else notify(message,true);}
function previewBody(){const screen=project.screens;return `<div class="segment"><button data-preview-tab="input" type="button" class="${previewTab==='input'?'active':''}">Input screen</button><button data-preview-tab="output" type="button" class="${previewTab==='output'?'active':''}">Output screen</button></div>${previewTab==='input'?`<div><h3>Set the input scope</h3><p class="small">${screen.input.length?'Field order follows your screen definition.':'No input fields defined yet.'}</p></div><div class="field-grid">${screen.input.map(f=>{const value=previewValues[f.id]??inputDefault(f);return `<label class="field"><span>${esc(f.label)}${f.required?' *':''}</span>${f.type==='Select'?`<select data-preview-input="${esc(f.id)}">${f.options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input data-preview-input="${esc(f.id)}" type="${f.type==='Date'?'date':f.type==='Number'?'number':'text'}" value="${esc(value)}">`}</label>`;}).join('')}</div>${button('Show sample output →','preview-output','','primary')}`:`<div><h3>${esc(project.steps.at(-1)?.output||'Final output')}</h3><div class="preview-scope">${screen.input.map(f=>`<span>${esc(f.label)}: ${esc(previewValues[f.id]??inputDefault(f))}</span>`).join('')}</div></div>${outputTable(screen)}<span class="sample-label">Sample values only · no live execution or tool connection</span>`}`;}
function outputTable(screen){return `<table class="preview-table"><thead><tr>${screen.output.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${screen.sampleRows.map(r=>`<tr>${screen.output.map(c=>`<td data-label="${esc(c)}">${esc(r[c]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function capturePreview(){document.querySelectorAll('[data-preview-input]').forEach(f=>previewValues[f.dataset.previewInput]=f.value);}
async function prepareReviewPacket(){try{const packet=await createIndependentReviewPacket(project,compile(project,{allowInvalid:true}));download(new Blob([JSON.stringify(packet,null,2)],{type:'application/json'}),project.slug+'-independent-review-packet.json');notify('Review packet prepared. No independent review has run.');}catch(error){notify(error.message,true);}}
function assetPreview(path,bytes){try{return new TextDecoder('utf-8',{fatal:true}).decode(bytes);}catch{return `${path}\n\nBinary asset retained unchanged (${bytes.length} bytes). Read its structural guide in Resources. Download the skill ZIP to inspect the original asset.`;}}
function analysisPayload(source){const bytes=sourceBytes(source);let value='';for(let i=0;i<bytes.length;i+=8192)value+=String.fromCharCode(...bytes.subarray(i,i+8192));return {path:source.path,data:btoa(value)};}
async function analyzeProjectSources(target){const paths=new Set(target.resources.filter(r=>r.untranslated.includes('Source analysis required')).map(r=>r.sourcePath));if(!paths.size)return;try{if(!/^https?:$/.test(location.protocol))throw new Error('Open the app through the local Studio server to use the source analyzer.');const response=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(target.originals.filter(o=>!o.path.endsWith('.md')&&o.encoding!=='unavailable').map(analysisPayload))});const analysis=await response.json();if(!response.ok||!Array.isArray(analysis))throw new Error(analysis.error||'The source analyzer is unavailable.');applyResourceAnalysis(target,analysis.filter(entry=>paths.has(entry.sourcePath)));}catch(error){target.importWarnings.push('Source analysis pending: '+error.message);}}
async function analyzePendingResources(){const originalId=project.id,revision=project.revision,target=copy(project);notify('Analyzing source behavior and structure locally…');await analyzeProjectSources(target);if(project?.id!==originalId||project.revision!==revision){notify('The draft changed during analysis. Run the analysis again.',true);return;}mutate(()=>{project.resources=target.resources;project.importWarnings=target.importWarnings;page='references';referenceTab='resources';},'Resource drafts updated. Review their instructions and step bindings.');}
async function prepareImport(files,destination=importDestination){const request=++importRequestToken;try{if(!workspaceProject(workspace,destination))throw new Error('Choose a project before importing a skill.');const incoming=importMarkdownFiles(files);if(incoming.resources.some(r=>r.untranslated.includes('Source analysis required'))){notify('Analyzing source behavior and asset structure locally…');await analyzeProjectSources(incoming);}if(request!==importRequestToken)return;if(!workspaceProject(workspace,destination))throw new Error('The destination project is no longer available.');pendingImport=incoming;pendingImportProjectId=destination;openDialog('import-review');}catch(error){if(request===importRequestToken)dialogError(error.message);}}

$('#dialog-form').addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.currentTarget),get=name=>String(data.get(name)||'').trim(),state=dialogState;if(!state)return;
 try{
  const mode=state.mode;
  if(mode==='create-workspace-project'||mode==='edit-workspace-project'){const name=get('projectName');if(!name||name.length>100)throw new Error('Use a project name between 1 and 100 characters.');save();if(mode==='create-workspace-project'){const container=addWorkspaceProject(workspace,createWorkspaceProject(name,get('projectDescription')));activeProjectId=container.id;project=null;page='skills';resetSkillView();}else{const container=workspaceProject(workspace,state.id);if(!container)throw new Error('That project is no longer available.');container.name=name;container.description=get('projectDescription');container.updatedAt=new Date().toISOString();}save();render();closeDialog();notify(mode==='create-workspace-project'?'Project created. Add your first skill.':'Project details saved.');return;}
  if(mode==='reset-workspace'){if(!data.has('confirmReset'))throw new Error('Confirm that you kept a recovery copy or do not need the earlier data.');workspace=emptyWorkspace();project=null;activeProjectId='';storageBlocked=false;recoveryText='';startupNotice='';page='projects';resetSkillView();save();render();closeDialog();return;}
  if(mode==='new'){if(!get('title')||!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(get('slug'))||get('slug').length>64)throw new Error('Add a title and a lowercase skill name separated by hyphens (up to 64 characters).');const skill=blankProject(get('title'));skill.slug=get('slug');skill.description=get('description');replaceProject(skill,'New skill added. Define its brief and first meaningful step.');closeDialog();return;}
if(mode==='import'){if(!get('markdown'))throw new Error('Choose a file or paste a skill.');await prepareImport({'SKILL.md':get('markdown')});return;}
  if(mode==='import-review'){replaceProject(pendingImport,'Imported skill added. Review its step boundaries and import notes.',pendingImportProjectId);pendingImport=null;closeDialog();return;}
  if(mode==='project'){if(!get('title')||!get('slug')||!get('description')||!get('input')||!get('outcome'))throw new Error('Complete the title, skill name, description, input, and final output.');const values=Object.fromEntries(['title','slug','description','purpose','input','outcome','instructions','extraFrontmatter'].map(k=>[k,get(k)]));if(mode==='new'){replaceProject({...blankProject(values.title),...values},'New skill created. Add its first meaningful step.');}else mutate(()=>Object.assign(project,values),'Skill brief updated.');}
  else if(mode==='add-step'||mode==='edit-step'){const values=Object.fromEntries(['title','kind','job','output','exampleInput','exampleOutput'].map(k=>[k,get(k)]));values.references=data.getAll('references').map(String);values.resourceIds=data.getAll('resourceIds').map(String);if(!values.title||!values.job||!values.output)throw new Error('Define the title, intended behavior, and output.');if(/[\r\n]/.test(values.output))throw new Error('Keep the output name on one line.');mutate(()=>{if(mode==='add-step'){const current=step(),i=current?project.steps.indexOf(current)+1:0;const added={...newStep(values.title),...values};project.steps.splice(i,0,added);selected=added.id;}else{const current=step();Object.assign(current,values);if(data.has('reviewed'))current.reviewed=true;}},'Step saved. Its output feeds the following step.');}
  else if(mode==='add-facet'||mode==='edit-facet'){const values=Object.fromEntries(['title','type','instructions','definitionId','override','connection','operation'].map(k=>[k,get(k)]));if(!values.title||!values.instructions)throw new Error('Define the facet name and instructions.');mutate(()=>{if(mode==='add-facet')step().facets.push({id:uid(),...values});else Object.assign(step().facets.find(f=>f.id===state.id),values);tab='facets';},'Facet saved inside this step.');}
  else if(mode==='add-reference'||mode==='edit-reference'){const path=get('path');if(!safePath(path)||!path.endsWith('.md')||path==='SKILL.md'||Object.values(PATHS).includes(path))throw new Error('Use a relative Markdown path outside the compiler’s reserved files.');if(project.references.some(r=>r.path===path&&r.id!==state.id))throw new Error('That reference path already exists.');mutate(()=>{if(mode==='add-reference'){const r={id:uid(),path,content:get('content')};project.references.push(r);referenceId=r.id;}else{const r=project.references.find(x=>x.id===state.id),old=r.path;r.path=path;r.content=get('content');project.steps.forEach(s=>s.references=s.references.map(p=>p===old?path:p));}page='references';referenceTab='files';},'Reference saved.');}
  else if(mode==='edit-resource'){const r=project.resources.find(x=>x.id===state.id),next={...r,...Object.fromEntries((r.policy==='generate'?CONTRACT_FIELDS:['structure']).map(key=>[key,get(key)])),dependencies:get('dependencies').split('\n').map(x=>x.trim()).filter(Boolean),untranslated:get('untranslated').split('\n').map(x=>x.trim()).filter(Boolean),reviewed:data.has('resourceReviewed')};if(next.reviewed&&!resourceComplete(next))throw new Error('Complete every contract field and resolve translation gaps before confirming review.');const bindings=data.getAll('resourceSteps').map(String);if(next.reviewed&&!bindings.length)throw new Error('Attach this resource to at least one workflow step.');mutate(()=>{Object.assign(r,next);for(const s of project.steps)s.resourceIds=bindings.includes(s.id)?[...new Set([...s.resourceIds,r.id])]:s.resourceIds.filter(x=>x!==r.id);page='references';referenceTab='resources';resourceId=r.id;resourceFilter=r.policy;},'Resource instructions and step bindings saved.');}
  else if(mode==='add-definition'||mode==='edit-definition'){mutate(()=>{const values={name:get('name'),value:get('value'),runtimeInput:get('runtimeInput'),intent:get('intent')};if(mode==='add-definition')project.definitions.push({id:uid(),...values});else Object.assign(project.definitions.find(d=>d.id===state.id),values);page='references';referenceTab='definitions';},'Shared definition updated. Linked facets follow its value.');}
  else if(mode==='add-field'||mode==='edit-field'){const values={label:get('label'),type:get('type'),defaultValue:get('defaultValue'),options:get('options').split('\n').map(x=>x.trim()).filter(Boolean),definitionId:get('definitionId'),required:data.has('required')};if(project.screens.input.some(f=>f.label===values.label&&f.id!==state.id))throw new Error('Each input field needs a unique label.');if(values.type==='Select'&&!values.options.length)throw new Error('Add choices for this Select field.');mutate(()=>{if(mode==='add-field')project.screens.input.push({id:uid(),...values});else{const current=project.screens.input.find(f=>f.id===state.id);project.definitions.forEach(d=>{if(d.runtimeInput===current.label)d.runtimeInput=values.label;});Object.assign(current,values);}page='screens';},'Input field saved.');}
  else if(mode==='columns'){const cols=get('columns').split('\n').map(x=>x.trim()).filter(Boolean);if(!cols.length||new Set(cols).size!==cols.length)throw new Error('Use unique column names, one per line.');mutate(()=>project.screens.output=cols,'Output column order updated.');}
  else if(mode==='screen-rules')mutate(()=>project.screens.instructions=get('instructions'),'Screen instructions saved.');
  else if(mode==='add-row'||mode==='edit-row'){const row=Object.fromEntries(project.screens.output.map((c,i)=>[c,get('column-'+i)]));mutate(()=>{if(mode==='add-row')project.screens.sampleRows.push(row);else project.screens.sampleRows[state.index]=row;page='screens';},'Example output row saved.');}
  else if(mode==='add-scenario'||mode==='edit-scenario'){const values={name:get('name'),input:get('input'),expected:get('expected')};mutate(()=>{if(mode==='add-scenario')project.scenarios.push({id:uid(),...values,status:'Not tested',testedRevision:null,observations:''});else Object.assign(project.scenarios.find(s=>s.id===state.id),values);page='scenarios';},'Scenario saved.');}
  else if(mode==='record-test'){if(!get('observations'))throw new Error('Record what happened in the actual test.');mutate(()=>{const t=project.scenarios.find(x=>x.id===state.id);t.status=get('status');t.observations=get('observations');t.testedRevision=t.status==='Not tested'?null:project.revision;},'Test observation recorded.',{definitionChange:false});}
  else if(mode==='import-notes')mutate(()=>project.warningsAcknowledged=data.has('acknowledged'),'Import review saved.',{definitionChange:false});
  else if(mode==='remove-step')mutate(()=>{const i=project.steps.findIndex(s=>s.id===selected);project.steps.splice(i,1);selected=project.steps[Math.max(0,i-1)]?.id||'';},'Step removed. Undo can restore it.');
  closeDialog();
 }catch(error){dialogError(error.message);}
});

document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.page){if(b.dataset.page==='projects'){showProjects();return;}if(b.dataset.page==='skills'){if(activeProjectId)openWorkspaceProject(activeProjectId);return;}if(!project)return;page=b.dataset.page;render();return;}
 if(b.dataset.view){view=b.dataset.view;render();return;}
 if(b.dataset.step){selected=b.dataset.step;if(window.innerWidth<690&&view==='flow')view='guided';render();return;}
 if(b.dataset.tab){tab=b.dataset.tab;render();return;}
 if(b.dataset.referenceTab){referenceTab=b.dataset.referenceTab;render();return;}
 if(b.dataset.reference){referenceId=b.dataset.reference;referenceTab='files';page='references';render();return;}
 if(b.dataset.resourceFilter){resourceFilter=b.dataset.resourceFilter;renderResources();return;}
 if(b.dataset.resource){resourceId=b.dataset.resource;const r=project.resources.find(x=>x.id===resourceId);resourceFilter=r?.policy||'generate';page='references';referenceTab='resources';render();return;}
 if(b.dataset.resourceStep){selected=b.dataset.resourceStep;page='workflow';tab='facets';render();return;}
 if(b.dataset.packageFile){packageFile=b.dataset.packageFile;render();return;}
 if(b.dataset.previewTab){capturePreview();previewTab=b.dataset.previewTab;openDialog('preview');return;}
 const action=b.dataset.action;if(!action)return;
 if(action==='projects'){showProjects();return;}
 if(action==='project-skills'){if(activeProjectId)openWorkspaceProject(activeProjectId);return;}
 if(action==='open-workspace-project'){openWorkspaceProject(b.dataset.id);return;}
 if(action==='open-skill'){openWorkspaceSkill(activeProjectId,b.dataset.id);return;}
 if(action==='restore-project'||action==='open-project'){restoreRequest={mode:'project',projectId:''};$('#project-file').value='';$('#project-file').click();return;}
 if(action==='restore-skill'){if(!currentContainer())return;restoreRequest={mode:'skill',projectId:activeProjectId};$('#project-file').value='';$('#project-file').click();return;}
 if(action==='download-recovery'){download(new Blob([recoveryText],{type:'application/json'}),'workspace-recovery.json');return;}
 if(action==='save-project'){save();const container=currentContainer();if(container)backupWorkspaceProject(container);else{download(new Blob([JSON.stringify(workspace,null,2)],{type:'application/json'}),'skill-blueprint-workspace.json');notify('Workspace backup prepared with every project and skill.');}return;}
 if(action==='save-skill'){if(!project)return;download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),project.slug+'.agentic.json');notify('Skill backup prepared, including source originals.');return;}
 if(action==='close'){closeDialog();return;}
 if(action==='undo'||action==='redo'){const from=action==='undo'?history:future,to=action==='undo'?future:history;if(from.length){to.push(copy(project));project=from.pop();save();render();notify(action==='undo'?'Change undone.':'Change restored.');}return;}
 if(action==='review-packet'){prepareReviewPacket();return;}
 if(action==='load-review-report'){$('#review-report-file').value='';$('#review-report-file').click();return;}

 if(action==='download-source'){try{const resource=project.originals.find(o=>o.path===b.dataset.path);download(new Blob([sourceBytes(resource)],{type:'application/octet-stream'}),resource.path.split('/').at(-1));}catch(error){notify(error.message,true);}return;}
 if(action==='download-originals'){try{const folder=(slugify(project.slug)||'original-skill')+'/';download(writeZip(Object.fromEntries(project.originals.map(o=>[o.archivePath||folder+o.path,sourceBytes(o)]))),(slugify(project.slug)||'original-skill')+'-source-originals.zip');notify('Original source bundle prepared with all retained file contents.');}catch(error){notify(error.message,true);}return;}

 if(action==='choose-import'){$('#skill-file').value='';$('#skill-file').click();return;}
 if(action==='import-reference'){$('#reference-file').value='';$('#reference-file').click();return;}
 if(action==='demo'){save();let container=workspace.projects.find(item=>item.isDemoProject===true);if(!container){container=createWorkspaceProject('Demo project','Explore the editor with an optional example skill.');container.isDemoProject=true;addWorkspaceProject(workspace,container);addWorkspaceSkill(workspace,container.id,demoProject());}if(!container.skills.length)addWorkspaceSkill(workspace,container.id,demoProject());save();openWorkspaceSkill(container.id,container.skills[0].id);notify('Demo opened. The shared-rule mismatch is intentional for review.');return;}
 if(action==='flow'){view='flow';render();return;}
 if(action==='facets'){tab='facets';render();return;}
 if(action==='resources'||action==='step-resources'){page='references';referenceTab='resources';if(action==='step-resources'){const attached=project.resources.find(r=>step().resourceIds.includes(r.id));if(attached){resourceId=attached.id;resourceFilter=attached.policy;}}render();return;}
 if(action==='attach-resources'){$('#resource-file').value='';$('#resource-file').click();return;}
 if(action==='analyze-resources'){analyzePendingResources();return;}
 if(action==='resource-source'){const resource=project.resources.find(r=>r.id===b.dataset.id),original=project.originals.find(o=>o.path===resource.sourcePath);if(!original){notify('This package contains the English specification. Original code is kept in its separate source archive.',true);return;}openDialog('originals');return;}
 if(action==='definitions'){page='references';referenceTab='definitions';render();return;}
 if(action==='previous'||action==='next'){const i=project.steps.indexOf(step()),next=i+(action==='next'?1:-1);if(project.steps[next]){selected=project.steps[next].id;render();}return;}
 if(action==='move-up'||action==='move-down'){mutate(()=>{const i=project.steps.indexOf(step()),to=i+(action==='move-up'?-1:1);if(to>=0&&to<project.steps.length){const [s]=project.steps.splice(i,1);project.steps.splice(to,0,s);}},'Step order updated. Inputs follow the new sequence.');return;}
 if(action==='approve'){const s=step();if(!s.job.trim()||!s.output.trim()||!project.input.trim()){openDialog('edit-step');dialogError('Define the overall input and this step’s job and output before confirming the proposal.');return;}mutate(()=>s.reviewed=true,'Imported step confirmed.');return;}
 if(action==='clear-override'){mutate(()=>step().facets.find(f=>f.id===b.dataset.id).override='','Facet now follows the shared definition.');return;}
 if(action==='remove-facet'){mutate(()=>{step().facets=step().facets.filter(f=>f.id!==b.dataset.id);tab='facets';},'Facet removed. Undo can restore it.');closeDialog();return;}
 if(action==='remove-reference'){mutate(()=>{project.references=project.references.filter(r=>r.id!==b.dataset.id);referenceId=project.references[0]?.id||'';},'Reference removed. Missing dependencies appear in review.');return;}
 if(action==='remove-definition'){mutate(()=>project.definitions=project.definitions.filter(d=>d.id!==b.dataset.id),'Definition removed. Linked facets need review.');return;}
 if(action==='remove-field'){mutate(()=>project.screens.input=project.screens.input.filter(f=>f.id!==b.dataset.id),'Input field removed.');closeDialog();return;}
 if(action==='move-field'){mutate(()=>{const i=project.screens.input.findIndex(f=>f.id===b.dataset.id);if(i>0){const [f]=project.screens.input.splice(i,1);project.screens.input.splice(i-1,0,f);}},'Input field order updated.');closeDialog();return;}
 if(action==='remove-row'){mutate(()=>project.screens.sampleRows.splice(Number(b.dataset.index),1),'Example row removed.');closeDialog();return;}
 if(action==='remove-scenario'){mutate(()=>project.scenarios=project.scenarios.filter(s=>s.id!==b.dataset.id),'Scenario removed.');closeDialog();return;}
 if(action==='preview-output'){capturePreview();const missing=project.screens.input.filter(f=>f.required&&!String(previewValues[f.id]??inputDefault(f)).trim());if(missing.length){dialogError('Complete the required inputs: '+missing.map(f=>f.label).join(', '));return;}previewTab='output';openDialog('preview');return;}
 if(action==='review-issue'){const issue=validate(project).errors[Number(b.dataset.index)];if(!issue)return;if(issue.stepId){selected=issue.stepId;page='workflow';tab=issue.field==='facets'?'facets':'definition';render();if(issue.field!=='facets')openDialog('edit-step');}else if(issue.field==='project')openDialog('project');else if(issue.field==='import')openDialog('import-notes');else if(issue.field==='adversarial'){page='package';render();}else{if(issue.field==='resources'){page='references';referenceTab='resources';const resource=project.resources.find(r=>issue.message.includes(r.sourcePath));if(resource){resourceId=resource.id;resourceFilter=resource.policy;}render();return;}page=issue.field==='screens'?'screens':issue.field==='definitions'||issue.field==='references'?'references':'workflow';if(issue.field==='definitions')referenceTab='definitions';render();}return;}
 if(action==='export'){try{const files=compile(project),folder=project.slug+'/';download(writeZip(Object.fromEntries(Object.entries(files).map(([path,text])=>[folder+path,text]))),project.slug+'.zip');notify('Skill ZIP prepared with English specifications and retained assets.');}catch(error){notify(error.message,true);}return;}
 openDialog(action,{id:b.dataset.id||'',index:Number(b.dataset.index??-1)});
});

document.addEventListener('input',event=>{if(dialogState?.mode==='new'&&event.target.name==='title'){const slug=$('#dialog-form [name="slug"]');if(!slug.dataset.manual)slug.value=slugify(event.target.value);}if(event.target.name==='slug')event.target.dataset.manual='true';});
$('#dialog').addEventListener('close',()=>{if(dialogState?.mode==='import'||dialogState?.mode==='import-review'){pendingImport=null;pendingImportProjectId='';importRequestToken++;}dialogState=null;});
$('#skill-file').addEventListener('change',async event=>{const file=event.target.files[0],destination=importDestination;if(!file)return;try{if(file.size>8*1024*1024)throw new Error('Import files up to 8 MB.');const files=file.name.toLowerCase().endsWith('.zip')?await readZip(await file.arrayBuffer()):{'SKILL.md':await file.text()};await prepareImport(files,destination);}catch(error){dialogError(error.message);}});
$('#project-file').addEventListener('change',async event=>{const file=event.target.files[0],request={...restoreRequest};if(!file)return;try{
 if(file.size>128*1024*1024)throw new Error('Backup files must be under 128 MB.');
 const text=await file.text();
 if(request.mode==='skill'){const skill=readProject(text),container=workspaceProject(workspace,request.projectId);if(!container)throw new Error('The destination project is no longer available.');if(container.skills.some(item=>item.id===skill.id))skill.id=uid();replaceProject(skill,'Skill backup restored into the project.',request.projectId);}
 else {const value=JSON.parse(text);save();if(value?.type==='skill-blueprint-workspace'){const incoming=readWorkspace(text);if(workspace.projects.length+incoming.projects.length>200)throw new Error('Restore would exceed the 200-project limit.');for(const container of incoming.projects)restoreWorkspaceProject(workspace,container);save();showProjects();notify(incoming.projects.length+' projects restored. Existing projects were preserved.');}else{const restored=restoreWorkspaceProject(workspace,readWorkspaceProjectBackup(text));save();openWorkspaceProject(restored.id);notify('Project restored with all its skills.');}}
 }catch(error){notify(error.message,true);}event.target.value='';});
$('#reference-file').addEventListener('change',async event=>{const skillId=project?.id,destination=activeProjectId;try{const files=[...event.target.files];if(files.some(f=>!f.name.endsWith('.md')||f.size>2*1024*1024))throw new Error('Choose Markdown files up to 2 MB each.');const refs=await Promise.all(files.map(async f=>({id:uid(),path:'references/'+f.name,content:await f.text()})));if(project?.id!==skillId||activeProjectId!==destination)throw new Error('The selected skill changed while the file was loading. Open the intended skill and try again.');if(refs.some(r=>project.references.some(x=>x.path===r.path))||new Set(refs.map(r=>r.path)).size!==refs.length)throw new Error('A reference with that name already exists. Edit it or rename the incoming file.');mutate(()=>{project.references.push(...refs);referenceId=refs[0]?.id||referenceId;page='references';referenceTab='files';},'Markdown references imported.');}catch(error){notify(error.message,true);}});
$('#resource-file').addEventListener('change',async event=>{const skillId=project?.id,destination=activeProjectId;try{const files=[...event.target.files];if(files.some(f=>f.size>8*1024*1024))throw new Error('Choose source files up to 8 MB each.');const sources=await Promise.all(files.map(async file=>preserveSource((/\.py$/i.test(file.name)?'scripts/':/\.html?$/i.test(file.name)?'templates/':/^license/i.test(file.name)?'':'assets/')+file.name,new Uint8Array(await file.arrayBuffer()))));if(project?.id!==skillId||activeProjectId!==destination)throw new Error('The selected skill changed while the file was loading. Open the intended skill and try again.');if(sources.some(o=>project.originals.some(x=>x.path===o.path))||new Set(sources.map(o=>o.path)).size!==sources.length)throw new Error('A source with that name is already preserved. Use a different filename.');mutate(()=>{project.originals.push(...sources);project.resources.push(...sources.map(draftResource));page='references';referenceTab='resources';resourceId=project.resources.at(-1)?.id||'';resourceFilter=project.resources.at(-1)?.policy||'generate';},'Complete source files attached.');await analyzePendingResources();}catch(error){notify(error.message,true);}});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();document.querySelector('[data-action="save-project"]').click();}});
const reviewReportInput=document.createElement('input');reviewReportInput.id='review-report-file';reviewReportInput.type='file';reviewReportInput.accept='.json';reviewReportInput.hidden=true;document.body.append(reviewReportInput);reviewReportInput.addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('Review reports must be at most 2 MB.');const report=JSON.parse(await file.text()),target=copy(project),base=project;await recordIndependentReview(target,report);if(base!==project||target.independentReview.snapshot!==reviewSnapshotForImport(project,target))throw new Error('The skill changed while the report was being checked. Try again.');mutate(()=>{project.independentReview=target.independentReview;page='package';},'Independent review report recorded.',{definitionChange:false});}catch(error){notify(error.message,true);}});
function reviewSnapshotForImport(current,target){return JSON.stringify(createReviewSnapshotData(current))===JSON.stringify(createReviewSnapshotData(target))?target.independentReview.snapshot:'';}
function createReviewSnapshotData(p){const value=copy(p);delete value.independentReview;return value;}
